#!/usr/bin/env node

// src/core/db-writer.ts
import {
  isNode,
  isSeq,
  Scalar
} from "yaml";
function quotedScalar(doc, value) {
  const node = doc.createNode(value);
  node.type = Scalar.QUOTE_DOUBLE;
  return node;
}
function addAliasesToNode(doc, ingNode, aliases) {
  const aliasesNode = ingNode.get("aliases", true);
  const existing = isSeq(aliasesNode) ? aliasesNode.toJSON() : [];
  const merged = Array.from(/* @__PURE__ */ new Set([...existing, ...aliases]));
  if (isSeq(aliasesNode)) {
    aliasesNode.items.length = 0;
    for (const a of merged) aliasesNode.add(quotedScalar(doc, a));
  } else {
    const seq = doc.createNode([]);
    for (const a of merged) seq.add(quotedScalar(doc, a));
    ingNode.set("aliases", seq);
  }
}
function removeIngredientKey(map, key) {
  const idx = map.items.findIndex((pair) => String(pair.key) === key);
  if (idx !== -1) map.items.splice(idx, 1);
}
function setProvenancedField(doc, map, key, value, provenance) {
  if (map.flow) map.flow = false;
  const node = doc.createNode(value);
  map.set(key, node);
  if (provenance) {
    const pair = map.items.find((p) => String(p.key) === key);
    if (pair && isNode(pair.value)) pair.value.comment = provenance;
  }
}

export {
  addAliasesToNode,
  removeIngredientKey,
  setProvenancedField
};
